class Solution:
    def minMaxWaitingTime(self, demand: List[int], fuel: List[int]) -> int:
        cur = {(fuel[0], fuel[1], 0, 0, 0): 0}
        ans = -1
        for d in demand:
            nxt = {}
            for (f0, f1, t0, t1, a), w in cur.items():
                fs, ts = (f0, f1), (t0, t1)
                for j in (0, 1):
                    if fs[j] < d:
                        continue
                    s = max(ts[j], a)
                    nw = max(w, s - a)
                    nf = list(fs); nf[j] -= d
                    nt = list(ts); nt[j] = s + d
                    key = (nf[0], nf[1], nt[0], nt[1], s)
                    if nxt.get(key, 10**9) > nw:
                        nxt[key] = nw
            cur = nxt
            if not cur:
                break
            ans = min(cur.values())
        return ans

