class Solution {
public:
    int minMaxWaitingTime(vector<int>& demand, vector<int>& fuel) {
        unordered_map<string,int> cur;
        cur[to_string(fuel[0]) + "," + to_string(fuel[1]) + ",0,0,0"] = 0;
        int ans = -1;
        for (int d : demand) {
            unordered_map<string,int> nxt;
            for (auto& [key, w] : cur) {
                int f0, f1, t0, t1, a;
                sscanf(key.c_str(), "%d,%d,%d,%d,%d", &f0, &f1, &t0, &t1, &a);
                int fs[2] = {f0, f1}, ts[2] = {t0, t1};
                for (int j = 0; j < 2; j++) {
                    if (fs[j] < d) continue;
                    int s = max(ts[j], a);
                    int nw = max(w, s - a);
                    int nf[2] = {fs[0], fs[1]}, nt[2] = {ts[0], ts[1]};
                    nf[j] -= d; nt[j] = s + d;
                    string nk = to_string(nf[0]) + "," + to_string(nf[1]) + "," +
                                to_string(nt[0]) + "," + to_string(nt[1]) + "," + to_string(s);
                    auto it = nxt.find(nk);
                    if (it == nxt.end() || it->second > nw) nxt[nk] = nw;
                }
            }
            cur = move(nxt);
            if (cur.empty()) break;
            ans = INT_MAX;
            for (auto& [k, v] : cur) ans = min(ans, v);
        }
        return ans;
    }
};

