class Solution {
    public int minMaxWaitingTime(int[] demand, int[] fuel) {
        Map<String, Integer> cur = new HashMap<>();
        cur.put(fuel[0] + "," + fuel[1] + ",0,0,0", 0);
        int ans = -1;
        for (int d : demand) {
            Map<String, Integer> nxt = new HashMap<>();
            for (Map.Entry<String, Integer> e : cur.entrySet()) {
                String[] p = e.getKey().split(",");
                int f0 = Integer.parseInt(p[0]), f1 = Integer.parseInt(p[1]);
                int t0 = Integer.parseInt(p[2]), t1 = Integer.parseInt(p[3]);
                int a = Integer.parseInt(p[4]), w = e.getValue();
                int[] fs = {f0, f1}, ts = {t0, t1};
                for (int j = 0; j < 2; j++) {
                    if (fs[j] < d) continue;
                    int s = Math.max(ts[j], a);
                    int nw = Math.max(w, s - a);
                    int[] nf = {fs[0], fs[1]}, nt = {ts[0], ts[1]};
                    nf[j] -= d; nt[j] = s + d;
                    String nk = nf[0] + "," + nf[1] + "," + nt[0] + "," + nt[1] + "," + s;
                    nxt.merge(nk, nw, Math::min);
                }
            }
            cur = nxt;
            if (cur.isEmpty()) break;
            ans = Collections.min(cur.values());
        }
        return ans;
    }
}

