class Solution:
    def minMaxWaitingTime(self, demand: List[int], fuel: List[int]) -> int:
        import functools
        n = len(demand)
        def ok(W):
            @functools.lru_cache(maxsize=None)
            def go(i, f0, f1, t0, t1, a):
                if i == n:
                    return True
                d = demand[i]
                for j in (0, 1):
                    f, t = (f0, t0) if j == 0 else (f1, t1)
                    if f < d:
                        continue
                    s = max(t, a)
                    if s - a > W:
                        continue
                    nf0, nf1 = (f0 - d, f1) if j == 0 else (f0, f1 - d)
                    nt0, nt1 = (s + d, t1) if j == 0 else (t0, s + d)
                    if go(i + 1, nf0, nf1, nt0, nt1, s):
                        return True
                return False
            return go(0, fuel[0], fuel[1], 0, 0, 0)
        lo, hi = 0, sum(demand)
        if not ok(hi):
            return -1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

