class Solution {
    int n;
    vector<int> dem;
    int limit;
    unordered_map<long long, bool> memo;
    bool go(int i, int f0, int f1, int t0, int t1, int a) {
        if (i == n) return true;
        long long key = (((((((long long)i * 60 + f0) * 60 + f1) * 2000 + t0) * 2000 + t1) * 2000 + a) * 2);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int d = dem[i];
        bool res = false;
        int fs[2] = {f0, f1}, ts[2] = {t0, t1};
        for (int j = 0; j < 2 && !res; j++) {
            if (fs[j] < d) continue;
            int s = max(ts[j], a);
            if (s - a > limit) continue;
            int nf[2] = {fs[0], fs[1]}, nt[2] = {ts[0], ts[1]};
            nf[j] -= d; nt[j] = s + d;
            res = go(i + 1, nf[0], nf[1], nt[0], nt[1], s);
        }
        return memo[key] = res;
    }
public:
    int minMaxWaitingTime(vector<int>& demand, vector<int>& fuel) {
        n = demand.size(); dem = demand;
        int lo = 0, hi = accumulate(demand.begin(), demand.end(), 0);
        limit = hi;
        memo.clear();
        if (!go(0, fuel[0], fuel[1], 0, 0, 0)) return -1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            limit = mid; memo.clear();
            if (go(0, fuel[0], fuel[1], 0, 0, 0)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

