    int[] dem;
    Map<Long, Boolean> memo;
    boolean go(int i, int f0, int f1, int t0, int t1, int a) {
        if (i == n) return true;
        long key = ((((((long) i * 60 + f0) * 60 + f1) * 2000L + t0) * 2000L + t1) * 2000L + a);
        Boolean m = memo.get(key);
        if (m != null) return m;
        int d = dem[i];
        boolean res = false;
        int[] fs = {f0, f1}, ts = {t0, t1};
        for (int j = 0; j < 2 && !res; j++) {
            if (fs[j] < d) continue;
            int s = Math.max(ts[j], a);
            if (s - a > limit) continue;
            int[] nf = {fs[0], fs[1]}, nt = {ts[0], ts[1]};
            nf[j] -= d; nt[j] = s + d;
            res = go(i + 1, nf[0], nf[1], nt[0], nt[1], s);
        }
        memo.put(key, res);
        return res;
    }
    public int minMaxWaitingTime(int[] demand, int[] fuel) {
        n = demand.length; dem = demand;
        int lo = 0, hi = 0;
        for (int x : demand) hi += x;
        limit = hi; memo = new HashMap<>();
        if (!go(0, fuel[0], fuel[1], 0, 0, 0)) return -1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            limit = mid; memo.clear();
            if (go(0, fuel[0], fuel[1], 0, 0, 0)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

