var minMaxWaitingTime = function(demand, fuel) {
    const n = demand.length;
    let limit = demand.reduce((a, b) => a + b, 0);
    const ok = () => {
        const memo = new Map();
        const go = (i, f0, f1, t0, t1, a) => {
            if (i === n) return true;
            const key = [i, f0, f1, t0, t1, a].join(',');
            if (memo.has(key)) return memo.get(key);
            const d = demand[i];
            let res = false;
            const fs = [f0, f1], ts = [t0, t1];
            for (let j = 0; j < 2 && !res; j++) {
                if (fs[j] < d) continue;
                const s = Math.max(ts[j], a);
                if (s - a > limit) continue;
                const nf = [...fs], nt = [...ts];
                nf[j] -= d; nt[j] = s + d;
                res = go(i + 1, nf[0], nf[1], nt[0], nt[1], s);
            }
            memo.set(key, res);
            return res;
        };
        return go(0, fuel[0], fuel[1], 0, 0, 0);
    };
    if (!ok()) return -1;
    let lo = 0, hi = limit;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        limit = mid;
        if (ok()) hi = mid; else lo = mid + 1;
    }
    return lo;
};
